from __future__ import annotations


class Group:
    def __init__(self, members: list[str]) -> None:
        self.members: list[str] = list(members)
        self._balances: dict[str, float] = {m: 0.0 for m in self.members}

    def add_expense(self, payer: str, amount: float,
                    participants: list[str] | None = None) -> None:
        if amount <= 0:
            raise ValueError("amount must be positive")
        if payer not in self._balances:
            raise ValueError(f"unknown payer: {payer}")

        if participants is None:
            participants = list(self.members)
        else:
            participants = list(participants)
            if not participants:
                raise ValueError("participants must be non-empty")
            for p in participants:
                if p not in self._balances:
                    raise ValueError(f"unknown participant: {p}")

        total_cents = round(amount * 100)
        n = len(participants)
        share = total_cents // n  # floor each participant's share

        self._balances[payer] += total_cents / 100.0

        for p in participants:
            if p == payer:
                # payer bears only the leftover cents, not the full share
                leftover = total_cents - share * n
                self._balances[p] -= leftover / 100.0
            else:
                self._balances[p] -= share / 100.0

    def balances(self) -> dict[str, float]:
        return {m: round(self._balances[m], 2) for m in self.members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        # Work in cents to avoid floating point issues
        cents = {m: round(self._balances[m] * 100) for m in self.members}

        debtors = sorted(
            [(m, -c) for m, c in cents.items() if c < 0],
            key=lambda x: (-x[1], x[0]),
        )
        creditors = sorted(
            [(m, c) for m, c in cents.items() if c > 0],
            key=lambda x: (-x[1], x[0]),
        )

        payments: list[tuple[str, str, float]] = []

        di = ci = 0
        d_rem = debtors[di][1] if debtors else 0
        c_rem = creditors[ci][1] if creditors else 0

        while di < len(debtors) and ci < len(creditors):
            pay = min(d_rem, c_rem)
            if pay >= 100:
                payments.append((debtors[di][0], creditors[ci][0], pay / 100.0))
            d_rem -= pay
            c_rem -= pay
            if d_rem == 0:
                di += 1
                if di < len(debtors):
                    d_rem = debtors[di][1]
            if c_rem == 0:
                ci += 1
                if ci < len(creditors):
                    c_rem = creditors[ci][1]

        return payments
